let activeLocale = 'en';

/** Set UI language from InvenTree context.locale. Unsupported languages fall back to English. */
export function selectLocale(locale) {
  activeLocale = String(locale || 'en').toLowerCase().split(/[-_]/)[0] === 'ru' ? 'ru' : 'en';
  return activeLocale;
}

/** Translate a stable key, replacing only named {parameters}. */
export function tr(key, parameters = {}) {
  const message = CATALOGS[activeLocale]?.[key] ?? CATALOGS.en[key] ?? key;
  return message.replace(/\{([a-z_]+)\}/gi, (match, name) =>
    Object.prototype.hasOwnProperty.call(parameters, name) ? String(parameters[name]) : match);
}
